<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/finance_step16.php';if(empty($_SESSION['fe_csrf']))$_SESSION['fe_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['fe_csrf'];$error=null;$success=null;$accounts=[];$income=[];$expense=[];$rows=[];
try{$pdo=business_db();finance_step16_ensure($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'add');if($action==='add'){$id=finance_step16_manual_transaction($pdo,$_POST);$success='Finance transaction #'.$id.' posted.';}elseif($action==='reverse'){finance_step16_reverse_manual($pdo,(int)($_POST['id']??0),(string)($_POST['reason']??''));$success='Finance transaction reversed with audit history.';}}$accounts=finance_step16_accounts($pdo,$orgId);$stmt=$pdo->prepare("SELECT * FROM finance_ledger_accounts WHERE organization_id=? AND account_class='income' AND status='active' ORDER BY account_name");$stmt->execute([$orgId]);$income=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT * FROM finance_ledger_accounts WHERE organization_id=? AND account_class='expense' AND status='active' ORDER BY account_name");$stmt->execute([$orgId]);$expense=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT m.*,j.journal_number FROM finance_manual_transactions m LEFT JOIN finance_journals j ON j.id=m.journal_id AND j.organization_id=m.organization_id WHERE m.organization_id=? ORDER BY m.transaction_date DESC,m.id DESC LIMIT 100");$stmt->execute([$orgId]);$rows=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function fe_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fe_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Finance Entry - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Manual Finance Entry</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_accounts.php">Accounts</a><a class="os-btn" href="finance_journal.php">Journal</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_accounts.php"><i class="dot"></i>Accounts</a><a class="active" href="finance_entry.php"><i class="dot"></i>Manual Entry</a><a href="finance_journal.php"><i class="dot"></i>Journal Ledger</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 16B • MANUAL JOURNAL WORKFLOW</div><h1>Record only finance facts that are not already coming from Sales or Purchases.</h1><p>Income, Expense and Transfer entries create balanced double-entry journals. Do not re-enter Product Sales or Supplier Payments here because those are already source-linked automatically.</p></section><?php if($error):?><div class="pp-alert bad"><strong>Entry diagnostic:</strong> <?= fe_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= fe_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="os-card" style="margin-top:14px"><h2>New Finance Entry</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= fe_h($csrf) ?>"><input type="hidden" name="action" value="add"><label>Transaction Date<input type="date" name="transaction_date" value="<?= date('Y-m-d') ?>" required></label><label>Type<select name="transaction_type" id="txType" onchange="toggleTx()"><option value="expense">Expense</option><option value="income">Income</option><option value="transfer">Transfer</option></select></label><label>Amount<input type="number" min="0.01" step="0.01" name="amount" required></label><div id="categoryBox"><label>Category<select name="category_ledger_account_id" id="category"><optgroup label="Expense" id="expenseGroup"><?php foreach($expense as $c):?><option value="<?= (int)$c['id'] ?>" data-class="expense"><?= fe_h($c['account_name']) ?></option><?php endforeach;?></optgroup><optgroup label="Income" id="incomeGroup"><?php foreach($income as $c):?><option value="<?= (int)$c['id'] ?>" data-class="income"><?= fe_h($c['account_name']) ?></option><?php endforeach;?></optgroup></select></label></div><div id="fromBox"><label>From Account<select name="from_cash_account_id"><option value="">Choose…</option><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>"><?= fe_h($a['account_name'].($a['is_system_clearing']?' • Clearing':'')) ?></option><?php endforeach;?></select></label></div><div id="toBox"><label>To Account<select name="to_cash_account_id"><option value="">Choose…</option><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>"><?= fe_h($a['account_name'].($a['is_system_clearing']?' • Clearing':'')) ?></option><?php endforeach;?></select></label></div><label>Memo<input name="memo" placeholder="What is this transaction for?" required></label><button>Post Balanced Entry →</button></form></section><section class="os-card" style="margin-top:14px"><h2>Manual Finance History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Journal</th><th>Type</th><th>Amount</th><th>Memo</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= fe_h($r['transaction_date']) ?></td><td><?= fe_h($r['journal_number']?:'—') ?></td><td><?= fe_h(strtoupper($r['transaction_type'])) ?></td><td><b><?= fe_m($r['amount']) ?></b></td><td><?= fe_h($r['memo']) ?></td><td><span class="pp-badge <?= $r['status']==='reversed'?'warn':'' ?>"><?= fe_h(strtoupper($r['status'])) ?></span></td><td><?php if($r['status']==='active'):?><details><summary>Reverse</summary><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= fe_h($csrf) ?>"><input type="hidden" name="action" value="reverse"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input name="reason" minlength="5" placeholder="Reason" required><button>Reverse →</button></form></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No manual finance entries yet.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Duplicate prevention:</strong> Product Sales, Customer Payments, Refunds, Supplier Bills and Supplier Payments are synced automatically and should not be entered manually.</div><script>function toggleTx(){const t=document.getElementById('txType').value;document.getElementById('categoryBox').style.display=t==='transfer'?'none':'block';document.getElementById('fromBox').style.display=t==='income'?'none':'block';document.getElementById('toBox').style.display=t==='expense'?'none':'block';const s=document.getElementById('category');if(t!=='transfer'){for(const o of s.options)o.hidden=o.dataset.class!==t;const first=[...s.options].find(o=>!o.hidden);if(first)s.value=first.value;}}toggleTx();</script><?php endif;?></main></div></body></html>